export interface Forecast {
	summary: string;
	tempC: number;
}

export async function fetchForecast(apiBase: string, city: string): Promise<Forecast | undefined> {
	const response = await fetch(`${apiBase}/forecast?city=${encodeURIComponent(city)}`);
	if (!response.ok) return undefined;
	return (await response.json()) as Forecast;
}

