content.text:
import { loadConfig } from "./config.ts";
import { fetchForecast } from "./net.ts";

export async function main(argv: string[]): Promise<number> {
	const city = argv[0];
	if (!city) {
		console.error("error");
		return 1;
	}
	let config;
	try {
		config = loadConfig(process.env.WEATHERLY_CONFIG ?? "weatherly.json");
	} catch (e) {
		console.error("bad config");
		return 2;
	}
	const forecast = await fetchForecast(config.apiBase, city);
	if (!forecast) {
		console.error("failed");
		return 3;
	}
	console.log(`${city}: ${forecast.summary}, ${forecast.tempC}°C`);
	return 0;
}

